Called mcp__forecasting__execute_squiggle with: {
  "code": "// Base Rate Model for AI Bio-Threat Design Capabilities
// Using historical data on AI breakthroughs in protein science

// Historical timeline from research:
// - 50 years of incremental progress (1974-2018)
// - 2018: AlphaFold breakthrough at CASP13
// - 2020: AlphaFold2 revolutionary breakthrough 
// - 2024: AlphaFold3 for complex interactions
// - 2025: First AI-designed proteins in trials

// Base rates for major capability leaps:
// Pre-2018: ~1 breakthrough per decade (10 years)
// Post-2018: ~1 breakthrough per 2-3 years

// Current protein design capabilities (2024-2025):
// - Component 1 (Novel Pathogen Design): ~40-50% → 10-12/25 points
// - Component 2 (Pandemic Optimization): ~20-30% → 5-7/25 points  
// - Component 3 (Synthesis Planning): ~15-25% → 4-6/25 points
// - Component 4 (Autonomy): ~30-40% → 7-10/25 points
// Total current: ~26-35/100 points

current_score = 30.5 // midpoint estimate
target_score = 75
gap_to_close = target_score - current_score

// Historical improvement rates:
// AlphaFold1 to AlphaFold2: ~300% accuracy improvement in 2 years
// AlphaFold2 to AlphaFold3: ~50-100% improvement in 4 years
// Average annual improvement: ~25-30% per year post-2018

annual_improvement_rate = 0.27 // 27% per year average

// Years needed to reach 75/100:
// Using exponential improvement: Score(t) = initial_score * (1 + rate)^t
years_needed = log(target_score / current_score) / log(1 + annual_improvement_rate)

// But biosecurity capabilities require convergence of 4 components
// Historical precedent: Complex multi-component AI systems take 1.5-2x longer
complexity_multiplier = 1.75

adjusted_years = years_needed * complexity_multiplier
forecast_year = 2025 + adjusted_years

{
  current_score: current_score,
  target_score: target_score,
  gap_to_close: gap_to_close,
  base_years_needed: years_needed,
  complexity_adjusted_years: adjusted_years,
  forecast_year: forecast_year
}",
  "model_name": "Base Rate Model"
}

