Called mcp__forecasting__execute_squiggle with: {
  "code": "// Outside View Model: Reference Class Forecasting
// Comparing ABTDT to similar complex multi-domain AI capabilities

// Reference Class 1: AlphaFold (protein structure prediction)
// - From concept (2016) to breakthrough (2020): 4 years
// - From breakthrough to practical application (2021-2024): 3 years
// - Total development time: 7 years

alphafold_development_years = 7

// Reference Class 2: Large Language Models (autonomous text generation)
// - From GPT-1 (2018) to GPT-4 level autonomy (2023): 5 years
// - From initial capability to reliable autonomous performance: 5 years

llm_development_years = 5

// Reference Class 3: Autonomous Driving (multi-sensor integration)
// - From first demos (2010) to current L4 capabilities (2024): 14 years
// - Still not fully autonomous in all conditions
// - Complex multi-component systems with safety requirements take longer

autonomous_driving_years = 14

// Reference Class 4: Drug Discovery AI (similar biosafety complexity)
// - From initial AI drug discovery (2015) to first approvals (2024): 9 years
// - Involves complex biological prediction and safety considerations

drug_discovery_years = 9

// Reference Class 5: Game AI (complex strategic reasoning)
// - From Deep Blue (1997) to AlphaGo (2016): 19 years
// - From AlphaGo to AlphaStar/OpenAI Five (2019): 3 years
// - Average for breakthrough strategic AI: ~11 years

strategic_ai_years = 11

// ABTDT complexity factors relative to reference classes:
// - Higher than AlphaFold (multi-component vs single prediction)
// - Higher than LLMs (requires physical world interaction)
// - Similar to autonomous driving (safety-critical, multi-component)
// - Similar to drug discovery (biosafety considerations)
// - Lower than strategic AI (more constrained domain)

reference_classes = [alphafold_development_years, llm_development_years, autonomous_driving_years, drug_discovery_years, strategic_ai_years]
weights = [0.15, 0.10, 0.30, 0.35, 0.10] // Weight by similarity to ABTDT

// Weighted average of reference classes
weighted_average = (alphafold_development_years * 0.15 + 
                   llm_development_years * 0.10 + 
                   autonomous_driving_years * 0.30 + 
                   drug_discovery_years * 0.35 + 
                   strategic_ai_years * 0.10)

// Adjust for ABTDT starting point (2025) vs reference class starting points
// ABTDT benefits from existing AI infrastructure (foundation models, compute)
// But faces unique biosafety challenges not present in most reference classes

infrastructure_advantage = -1.5 // 1.5 years faster due to existing AI infrastructure
biosafety_penalty = +2.0 // 2 years slower due to biosafety considerations

adjusted_years = weighted_average + infrastructure_advantage + biosafety_penalty
forecast_year = 2025 + adjusted_years

{
  reference_classes: reference_classes,
  weights: weights,
  weighted_average: weighted_average,
  infrastructure_advantage: infrastructure_advantage,
  biosafety_penalty: biosafety_penalty,
  adjusted_years: adjusted_years,
  forecast_year: forecast_year
}",
  "model_name": "Outside View Model"
}

