Called mcp__forecasting__execute_squiggle with: {
  "code": "// Trend Extrapolation Model: Projecting Current AI Capability Trajectories
// Based on observed trends from research data

// Current AI Performance Trends (from research):

// 1. Protein Design Success Rates:
// - 2022: RFDiffusion ~10% success rate for complex targets
// - 2025: Reported 35% success rate for similar targets (3.5x improvement in 3 years)
// - Annual improvement: (35/10)^(1/3) - 1 = 52% per year

protein_design_current_success = 0.35
protein_design_annual_growth = 0.52

// 2. Synthesis Planning Capability:
// - 2024: Minimal capability (<20% accurate protocols)
// - 2025: Cradle's "lab-in-the-loop" achieves 100% success in specific challenges
// - But still limited to narrow domains
// - Current overall capability: ~20-25%

synthesis_current = 0.225
synthesis_annual_growth = 0.35 // High growth from low base

// 3. AI Autonomy in Biology:
// - 2023: Heavy human guidance required
// - 2024: AlphaFold 3 more autonomous structure prediction
// - 2025: First autonomous experiment design systems
// - OpenAI predicts intern-level AI researcher by 2026 (75% confidence)

autonomy_current = 0.35
autonomy_annual_growth = 0.25 // Based on OpenAI timeline

// 4. Multi-objective Optimization (pandemic characteristics):
// - Currently very limited capability
// - No AI can reliably optimize for multiple viral characteristics
// - Slowest growing component

pandemic_opt_current = 0.25
pandemic_opt_annual_growth = 0.12 // Conservative - requires major breakthroughs

// Model each component reaching threshold capability (75% of max)
threshold = 0.75

years_to_protein_threshold = log(threshold / protein_design_current_success) / log(1 + protein_design_annual_growth)
years_to_synthesis_threshold = log(threshold / synthesis_current) / log(1 + synthesis_annual_growth)  
years_to_autonomy_threshold = log(threshold / autonomy_current) / log(1 + autonomy_annual_growth)
years_to_pandemic_threshold = log(threshold / pandemic_opt_current) / log(1 + pandemic_opt_annual_growth)

// System integration time: historically 12-18 months for complex AI systems
integration_years = 1.5

// Total time is bottleneck component + integration
bottleneck_years = max([years_to_protein_threshold, years_to_synthesis_threshold, years_to_autonomy_threshold, years_to_pandemic_threshold])

total_years = bottleneck_years + integration_years
forecast_year = 2025 + total_years

// Account for potential slowdowns as capabilities approach theoretical limits
// S-curve effect: growth slows as performance approaches 100%
sigmoid_adjustment = 1.2 // 20% longer due to diminishing returns

adjusted_total_years = total_years * sigmoid_adjustment
adjusted_forecast_year = 2025 + adjusted_total_years

{
  protein_years: years_to_protein_threshold,
  synthesis_years: years_to_synthesis_threshold,
  autonomy_years: years_to_autonomy_threshold,
  pandemic_years: years_to_pandemic_threshold,
  bottleneck_years: bottleneck_years,
  total_years: total_years,
  adjusted_total_years: adjusted_total_years,
  forecast_year: forecast_year,
  adjusted_forecast_year: adjusted_forecast_year
}",
  "model_name": "Trend Extrapolation Model"
}

