Called mcp__forecasting__execute_squiggle with: {
  "code": "// Expert Consensus Model: Aggregating Expert Predictions
// Using expert predictions from research with track record weighting

// Expert 1: OpenAI Leadership (Sam Altman, Jakob Pachocki)
// Prediction: Intern-level AI researcher by Sep 2026, full researcher by Mar 2028
// Applied to ABTDT: Advanced biological design capability by 2028-2029
// Track record: High (correctly predicted GPT capabilities)
// Weight: 20%

openai_prediction_year = 2029
openai_weight = 0.20

// Expert 2: David Baker (Nobel Prize winner, University of Washington)
// Prediction: From research, protein design becoming "prescriptive" by 2030
// But Baker emphasizes need for experimental validation, suggests slower timeline
// Track record: Very high (pioneered computational protein design)
// Weight: 25%

baker_prediction_year = 2032
baker_weight = 0.25

// Expert 3: Epoch AI Research Collective
// Prediction: AI will solve protein-ligand benchmarks by ~2027-2028
// Protein-protein interactions by 2029-2030
// But complex multi-objective optimization will take longer
// Track record: High (accurate ML capability predictions)
// Weight: 15%

epoch_ai_prediction_year = 2033
epoch_ai_weight = 0.15

// Expert 4: Dr. Minkyung Baek (Seoul National University, 2025 ASPIRE Prize)
// Prediction: AI-powered protein structure prediction mature, but design still evolving
// Estimate: Full autonomous design capabilities by 2031-2032
// Track record: High (RoseTTAFold development)
// Weight: 15%

baek_prediction_year = 2031
baek_weight = 0.15

// Expert 5: Biosecurity Community (aggregated view)
// Prediction: Based on Microsoft research revealing AI biosecurity vulnerabilities
// Consensus: Dangerous capabilities emerging faster than expected
// Conservative estimate to account for adversarial use: 2030-2033
// Track record: Medium (new field, but important perspective)
// Weight: 10%

biosecurity_prediction_year = 2033
biosecurity_weight = 0.10

// Expert 6: Industry Leaders (Merck, Generate Biomedicines, etc.)
// Prediction: Commercial protein design platforms scaling rapidly
// Market-driven timeline suggests capabilities by 2028-2030
// Track record: Medium-High (industry has incentives for accuracy)
// Weight: 15%

industry_prediction_year = 2029
industry_weight = 0.15

// Calculate weighted consensus
weighted_consensus = (openai_prediction_year * openai_weight +
                     baker_prediction_year * baker_weight +
                     epoch_ai_prediction_year * epoch_ai_weight +
                     baek_prediction_year * baek_weight +
                     biosecurity_prediction_year * biosecurity_weight +
                     industry_prediction_year * industry_weight)

// Uncertainty adjustment: Expert predictions often optimistic for complex systems
// Add 10% uncertainty buffer based on historical AI prediction accuracy

uncertainty_buffer = weighted_consensus * 0.05 // 5% buffer
final_prediction = weighted_consensus + uncertainty_buffer

// Also calculate confidence-weighted median for comparison
expert_predictions = [openai_prediction_year, baker_prediction_year, epoch_ai_prediction_year, baek_prediction_year, biosecurity_prediction_year, industry_prediction_year]
median_prediction = 2031 // manually calculated median

{
  expert_predictions: expert_predictions,
  weights: [openai_weight, baker_weight, epoch_ai_weight, baek_weight, biosecurity_weight, industry_weight],
  weighted_consensus: weighted_consensus,
  uncertainty_buffer: uncertainty_buffer,
  final_prediction: final_prediction,
  median_prediction: median_prediction
}",
  "model_name": "Expert Consensus Model"
}

